import React from 'react';

const WeeklyView = ({ tasks, goals, events, onToggleTask, onToggleGoal, onEditTask, onEditGoal, onEditEvent }) => {
  const today = new Date();
  const monday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - today.getDay() + 1, 12, 0, 0);

  const weekDays = [];
  for (let i = 0; i < 7; i++) {
    const day = new Date(monday);
    day.setDate(monday.getDate() + i);
    weekDays.push(day);
  }

  const formatDate = (dateString) => {
    if (!dateString) return 'No date';
    const date = new Date(dateString + 'T00:00:00');
    return date.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  const getItemsForDay = (dayDate) => {
    const dayStr = dayDate.toISOString().split('T')[0];

    const dayTasks = tasks.filter(task => task.date === dayStr);
    const dayGoals = goals.filter(goal => goal.deadline === dayStr);
    const dayEvents = events.filter(event => {
      if (event.start) {
        return event.start.split('T')[0] === dayStr;
      }
      return event.date === dayStr;
    });

    return { tasks: dayTasks, goals: dayGoals, events: dayEvents };
  };

  const handleItemClick = (item, type) => {
    if (type === 'tasks') {
      onEditTask(item);
    } else if (type === 'goals') {
      onEditGoal(item);
    } else if (type === 'events') {
      onEditEvent(item);
    }
  };

  const renderItem = (item, type) => {
    const isCompleted = item.completed || false;

    return (
      <div 
        key={item.id} 
        className={`weekly-item ${type} ${isCompleted ? 'completed' : ''}`}
        onClick={() => handleItemClick(item, type)}
        style={{
          cursor: 'pointer',
          padding: '4px 8px',
          margin: '2px 0',
          borderRadius: '4px',
          fontSize: '12px',
          backgroundColor: isCompleted ? '#e8f5e8' : '#f8f9fa',
          border: `1px solid ${isCompleted ? '#28a745' : '#dee2e6'}`,
          textDecoration: isCompleted ? 'line-through' : 'none',
          opacity: isCompleted ? 0.7 : 1
        }}
      >
        <div style={{ fontWeight: 'bold', color: '#2c3e50' }}>
          {item.task || item.name || item.title}
        </div>
        {type === 'events' && item.start && (
          <div style={{ color: '#6c757d', fontSize: '10px' }}>
            {new Date(item.start).toLocaleTimeString('en-US', { 
              hour: 'numeric', 
              minute: '2-digit', 
              hour12: true 
            })}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="card">
      <h3>Weekly View</h3>
      <div style={{ display: 'flex', gap: '10px', overflowX: 'auto' }}>
        {weekDays.map((day, index) => {
          const dayItems = getItemsForDay(day);
          const isToday = day.toDateString() === today.toDateString();

          return (
            <div 
              key={index} 
              style={{ 
                minWidth: '150px', 
                padding: '10px', 
                border: '1px solid #ddd', 
                borderRadius: '8px',
                backgroundColor: isToday ? '#e3f2fd' : '#f9f9f9'
              }}
            >
              <h4 style={{ 
                margin: '0 0 10px 0', 
                textAlign: 'center',
                color: isToday ? '#1976d2' : '#333'
              }}>
                {day.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
                {isToday && <div style={{ fontSize: '10px', color: '#1976d2' }}>TODAY</div>}
              </h4>

              <div>
                {dayItems.tasks.map(task => renderItem(task, 'tasks'))}
                {dayItems.goals.map(goal => renderItem(goal, 'goals'))}
                {dayItems.events.map(event => renderItem(event, 'events'))}

                {dayItems.tasks.length === 0 && dayItems.goals.length === 0 && dayItems.events.length === 0 && (
                  <div style={{ color: '#999', fontSize: '12px', textAlign: 'center', padding: '20px 0' }}>
                    No items
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default WeeklyView;
